import json

slug = (params.get("practice_slug") or "").strip()
problem = ""
settings = {}

def read_json(path):
    try:
        raw = api.files.read(file=path, scope="org")
    except Exception as exc:
        return None, "Couldn't read " + path + ": " + str(exc)
    try:
        return json.loads(raw), None
    except Exception as exc:
        return None, path + " isn't valid JSON (" + str(exc) + ")"

# No slug set (the param ships blank and can't be edited in the app): use
# the practice settings file, as long as there's exactly one.
if not slug:
    try:
        practice_entries = api.files.list(path="PracticeManager/Practices", scope="org") or []
    except Exception:
        practice_entries = []
    practice_slugs = []
    for e in practice_entries:
        name = str((e.get("name") if isinstance(e, dict) else e) or "").split("/")[-1]
        if name.endswith(".json"):
            practice_slugs.append(name[: -len(".json")])
    if len(practice_slugs) == 1:
        slug = practice_slugs[0]

if not slug:
    problem = "No practice_slug configured for this automation, and there isn't exactly one practice settings file in PracticeManager/Practices to fall back on."
else:
    found, err = read_json("PracticeManager/Practices/" + slug + ".json")
    if found is None:
        problem = err or ("No practice settings file found for slug '" + slug + "'.")
    else:
        settings = found

import json

slug = params["slug"]
prefix = slug + "-gap-offers-"

try:
    entries = api.files.list(path="PracticeManager/State", scope="org") or []
except Exception:
    entries = []

# Written by "Send approved slot offers" once offers go out; only the ones
# still waiting for a YES are checked.
open_offers = []
for e in entries:
    name = str((e.get("name") if isinstance(e, dict) else e) or "").split("/")[-1]
    if not (name.startswith(prefix) and name.endswith(".json")):
        continue
    try:
        data = json.loads(api.files.read(file="PracticeManager/State/" + name, scope="org") or "{}") or {}
    except Exception:
        continue
    if isinstance(data, dict) and data.get("status") == "awaiting_reply":
        data["_file_name"] = name
        open_offers.append(data)

import json
import re
import html
import datetime

def cliniko(tool, args):
    return api.connectors.invoke(server="cliniko-scheduling", tool=tool, args=args) or {}

def link_id(obj, key):
    link = ((obj.get(key) or {}).get("links") or {}).get("self") or ""
    return link.rstrip("/").split("/")[-1] if link else ""

def parse(iso_str):
    return datetime.datetime.fromisoformat(iso_str.replace("Z", "+00:00"))

def zulu(dt):
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def read_json(path):
    try:
        return json.loads(api.files.read(file=path, scope="org") or "null")
    except Exception:
        return None

def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True), scope="org")

def comment(body):
    try:
        api.workq.comment(todo_id=todo_id, body=body)
    except Exception:
        pass

def as_html(text):
    # Graph treats reply/send bodies here as HTML: escape, then real <br>s.
    return html.escape(text).replace("\n", "<br>")

def reply_to(message_id, text):
    api.connectors.invoke(server="m365-mail-send", tool="reply_to_email",
                          args={"id": message_id, "comment": as_html(text)})

slug = str(params["slug"] or "")
settings = params["settings"] or {}
record = dict(params["offer"] or {})
file_name = str(record.pop("_file_name", "") or "")
state_path = "PracticeManager/State/" + file_name
todo_id = str(record.get("todo_id") or "")
slot = record.get("slot") or {}
slot_label = str(record.get("slot_label") or "")
subject = str(record.get("subject") or "")
sent_at = str(record.get("sent_at") or "")
offered = [o for o in (record.get("offered") or []) if isinstance(o, dict)]
practice_name = str(settings.get("name") or "")
sign_off = practice_name or "Kind regards"
now = datetime.datetime.now(datetime.timezone.utc)

result = "no_reply_yet"
seen_ids = [str(i) for i in (record.get("seen_reply_ids") or [])]
replies_log = [r for r in (record.get("replies") or []) if isinstance(r, dict)]

try:
    slot_start = parse(str(slot.get("starts_at") or ""))
    slot_end = parse(str(slot.get("ends_at") or "")) if slot.get("ends_at") else slot_start + datetime.timedelta(minutes=30)
except Exception:
    slot_start = None
    slot_end = None

if not slot_start or not slot_end or not todo_id or not offered:
    result = "incomplete_record"
    record["status"] = "incomplete"
elif slot_start <= now:
    # Nobody said YES before the slot started -- stop watching.
    result = "expired"
    record["status"] = "expired"
    comment("No patient replied YES before " + slot_label + ", so the slot wasn't filled.")
    try:
        api.workq.complete(todo_id=todo_id)
    except Exception:
        pass
else:
    # 1. New replies from the offered patients to this slot's offer email.
    by_email = {str(o.get("email") or "").strip().lower(): o for o in offered if o.get("email")}
    raw = api.connectors.invoke(server="m365-mail-read", tool="list_emails", args={"folder": "inbox", "limit": 50})
    messages = raw if isinstance(raw, list) else ((raw or {}).get("value") or [])
    new_replies = []
    for m in messages:
        if not isinstance(m, dict):
            continue
        sender = str(((m.get("from") or {}).get("emailAddress") or {}).get("address") or "").strip().lower()
        received = str(m.get("receivedDateTime") or "")
        msg_id = str(m.get("id") or "")
        if (sender in by_email and msg_id and msg_id not in seen_ids and received > sent_at
                and slot_label and slot_label in str(m.get("subject") or "")):
            new_replies.append(m)
    new_replies.sort(key=lambda m: str(m.get("receivedDateTime") or ""))

    # 2. Read each reply properly and let AI decide YES / NO / unclear.
    winner = None
    winner_msg_id = ""
    for m in new_replies:
        msg_id = str(m.get("id") or "")
        sender = str(((m.get("from") or {}).get("emailAddress") or {}).get("address") or "").strip().lower()
        text = ""
        try:
            full = api.connectors.invoke(server="m365-mail-read", tool="get_email", args={"id": msg_id}) or {}
            content = str((full.get("body") or {}).get("content") or "")
            plain = re.sub(r"(?i)<br\s*/?>|</p>|</div>|</tr>", "\n", content)
            plain = re.sub(r"<[^>]+>", " ", plain)
            plain = re.sub(r"[ \t]+", " ", html.unescape(plain))
            # Cut the quoted offer off so its own "reply YES" never counts.
            quote_start = re.search(r"(?im)^\s*(From:|Sent:|On .{0,80} wrote:|-+ ?Original Message)", plain)
            if quote_start:
                plain = plain[: quote_start.start()]
            text = re.sub(r"\s+", " ", plain).strip()
        except Exception:
            text = ""
        if not text:
            text = str(m.get("bodyPreview") or "")
        answer = "unclear"
        try:
            ai_raw = str(api.ai.generate(prompt=(
                "A patient was offered an earlier appointment on " + slot_label
                + " and told to reply YES to take it. Their reply:\n\"" + text[:1500] + "\"\n\n"
                "Are they accepting this appointment? Reply with ONLY JSON, no markdown: "
                '{"answer": "yes" | "no" | "unclear"}'
            )) or "")
            cleaned = ai_raw.strip().strip("`").strip()
            if cleaned.lower().startswith("json"):
                cleaned = cleaned[4:]
            answer = str((json.loads(cleaned.strip()) or {}).get("answer") or "unclear").lower()
        except Exception:
            answer = "yes" if re.match(r"^\s*(yes|yep|yeah|sure|ok|okay)\b", text, re.I) else "unclear"
        seen_ids.append(msg_id)
        patient = by_email.get(sender) or {}
        replies_log.append({"from": sender, "name": str(patient.get("name") or ""), "answer": answer,
                            "received": str(m.get("receivedDateTime") or ""), "text": text[:300]})
        if answer == "yes" and winner is None:
            winner = patient
            winner_msg_id = msg_id
        elif answer == "unclear":
            comment("Unclear reply from " + str(patient.get("name") or sender) + " about this slot: \"" + text[:300]
                    + "\". Not booked; please follow up with them.")
        elif answer == "no":
            comment(str(patient.get("name") or sender) + " declined the offer.")

    if winner is not None:
        # 3. Book the first YES, if the slot is still free.
        own_appt_id = str(winner.get("appointment_id") or "")
        current = {}
        length = slot_end - slot_start
        if own_appt_id:
            try:
                current = cliniko("get_individual_appointment", {"id": own_appt_id}) or {}
                length = parse(str(current.get("ends_at") or "")) - parse(str(current.get("starts_at") or ""))
            except Exception:
                current = current or {}
        new_end = slot_start + length
        practitioner_id = str(slot.get("practitioner_id") or "")
        taken = False
        try:
            nearby = cliniko("list_individual_appointments", {
                "q": ["starts_at:>=" + zulu(slot_start - datetime.timedelta(hours=4)), "starts_at:<" + zulu(new_end),
                      "practitioner_id:=" + practitioner_id],
                "per_page": 100,
            }).get("individual_appointments") or []
        except Exception:
            nearby = []
        for other in nearby:
            if other.get("cancelled_at") or other.get("archived_at") or other.get("deleted_at"):
                continue
            if str(other.get("id") or "") == own_appt_id or link_id(other, "practitioner") != practitioner_id:
                continue
            try:
                if parse(str(other.get("starts_at") or "")) < new_end and parse(str(other.get("ends_at") or "")) > slot_start:
                    taken = True
                    break
            except Exception:
                continue

        first_name = str(winner.get("name") or "").split(" ")[0] or "there"
        if taken:
            result = "taken"
            record["status"] = "taken"
            try:
                reply_to(winner_msg_id, "Hi " + first_name + ",\n\nThank you for replying. Unfortunately the "
                         + slot_label + " appointment has just been taken, so your current booking stays as it is.\n\n" + sign_off)
            except Exception:
                pass
            comment(str(winner.get("name") or "") + " said YES, but someone was booked into the slot in Cliniko first. They've been told their booking is unchanged.")
            try:
                api.workq.complete(todo_id=todo_id)
            except Exception:
                pass
        else:
            book_error = ""
            try:
                if own_appt_id:
                    # Already booked later: move that booking into the slot
                    # (keeping its length) rather than double-booking them.
                    cliniko("update_individual_appointment", {"id": own_appt_id,
                            "patch": {"starts_at": zulu(slot_start), "ends_at": zulu(new_end)}})
                else:
                    cliniko("create_individual_appointment", {"appointment": {
                        "patient_id": str(winner.get("patient_id") or ""),
                        "practitioner_id": practitioner_id,
                        "business_id": str(slot.get("business_id") or ""),
                        "appointment_type_id": str(slot.get("appointment_type_id") or ""),
                        "starts_at": zulu(slot_start),
                        "ends_at": zulu(new_end),
                    }})
            except Exception as exc:
                book_error = str(exc)

            if book_error:
                result = "booking_failed"
                record["status"] = "needs_human"
                comment(str(winner.get("name") or "") + " replied YES, but Cliniko rejected the booking: " + book_error[:300]
                        + "\n\nPlease book them into " + slot_label + " manually and reply to them yourself.")
            else:
                result = "booked"
                record["status"] = "filled"
                record["filled_by"] = {"name": winner.get("name"), "email": winner.get("email"), "patient_id": winner.get("patient_id")}
                moved_from = str(winner.get("current_label") or "")
                try:
                    reply_to(winner_msg_id, "Hi " + first_name + ",\n\nYou're booked in for " + slot_label
                             + (". Your " + moved_from + " appointment has been moved to this time" if own_appt_id and moved_from else "")
                             + ". See you then!\n\n" + sign_off)
                except Exception:
                    comment("Booked, but the confirmation email to " + str(winner.get("name") or "") + " failed to send; please let them know.")
                # Tell everyone else who was offered it that it's gone.
                for o in offered:
                    if str(o.get("email") or "").strip().lower() == str(winner.get("email") or "").strip().lower():
                        continue
                    try:
                        api.connectors.invoke(server="m365-mail-send", tool="send_email", args={
                            "to": [str(o.get("email") or "")], "subject": "RE: " + subject, "contentType": "Text",
                            "body": "Hi " + (str(o.get("name") or "").split(" ")[0] or "there") + ",\n\nThank you for your interest. The "
                                    + slot_label + " appointment has now been filled"
                                    + (", so your current booking stays as it is." if o.get("appointment_id") else ".")
                                    + "\n\n" + sign_off,
                        })
                    except Exception:
                        pass
                # A moved booking frees its old time: leave it for "Find freed
                # slots to fill", the same note the reschedule desk leaves.
                if own_appt_id and current.get("starts_at"):
                    try:
                        freed_path = "PracticeManager/State/" + slug + "-freed-slots.json"
                        freed = read_json(freed_path)
                        freed = freed if isinstance(freed, list) else []
                        freed.append({
                            "appointment_id": own_appt_id,
                            "patient_id": link_id(current, "patient"),
                            "starts_at": str(current.get("starts_at") or ""),
                            "ends_at": str(current.get("ends_at") or ""),
                            "practitioner_id": link_id(current, "practitioner"),
                            "business_id": link_id(current, "business"),
                            "appointment_type_id": link_id(current, "appointment_type"),
                            "freed_at": zulu(now),
                        })
                        write_json(freed_path, freed[-200:])
                    except Exception:
                        pass
                others = [str(o.get("name") or "") for o in offered if o is not winner]
                comment("✅ Filled: " + str(winner.get("name") or "") + " replied YES and is booked into " + slot_label
                        + (" (moved from " + moved_from + ")" if own_appt_id and moved_from else "") + " in Cliniko. Confirmation sent."
                        + (" Told " + ", ".join(others) + " the slot is filled." if others else ""))
                try:
                    api.workq.complete(todo_id=todo_id)
                except Exception:
                    pass

                # Audit trail (healthcare-practice-management-guardrail-audit format).
                try:
                    from zoneinfo import ZoneInfo
                    today_str = now.astimezone(ZoneInfo(str(settings.get("timezone") or "UTC"))).date().isoformat()
                except Exception:
                    today_str = now.date().isoformat()
                audit_path = "PracticeManager/AuditLog/" + slug + "-" + today_str + ".jsonl"
                try:
                    existing_log = api.files.read(file=audit_path, scope="org")
                except Exception:
                    existing_log = ""
                try:
                    api.files.put(file=audit_path, scope="org", content=existing_log + json.dumps({
                        "ts": zulu(now), "practice_slug": slug, "actor": "agent",
                        "source": "automation:Cliniko Automations: Book the first YES for a freed slot",
                        "action": "booked", "target": {"kind": "appointment_slot", "id": str(slot.get("key") or "")},
                        "summary": "Freed slot " + slot_label + " filled by " + str(winner.get("name") or ""),
                        "guardrails": [{"rule": "diary_change_requires_approval", "result": "pass",
                                        "detail": "offer approved in WorkQ; patient accepted by email"}],
                        "workq_item_id": todo_id,
                    }, sort_keys=True) + "\n")
                except Exception:
                    pass
    elif new_replies:
        result = "replies_no_yes"

record["seen_reply_ids"] = seen_ids[-200:]
record["replies"] = replies_log[-50:]
record["checked_at"] = zulu(now)
if file_name:
    write_json(state_path, record)
